window.__fixLinksPrev = [];
const AMBIGUOUS = ['click here', 'here', 'read more', 'more', 'learn more', 'continue', 'link', 'this', 'this link'];
const isVisible = (el) => {
  if (!el.isConnected) return false;
  const style = window.getComputedStyle(el);
  if (style.display === 'none' || style.visibility === 'hidden' || style.opacity === '0') return false;
  const rect = el.getBoundingClientRect();
  return rect.width > 0 && rect.height > 0;
};
const links = Array.from(document.querySelectorAll('a[href]')).filter(a => {
  if (a.dataset.ai4a11yProcessed) return false;
  if (!isVisible(a)) return false;
  const name = (a.getAttribute('aria-label') || a.querySelector('img')?.getAttribute('alt') || a.textContent || '').trim().toLowerCase();
  return AMBIGUOUS.includes(name);
});
for (const link of links) {
  window.__fixLinksPrev.push({
    link,
    ariaLabel: link.getAttribute('aria-label'),
    hadAriaLabel: link.hasAttribute('aria-label'),
    className: link.getAttribute('class'),
    hadClass: link.hasAttribute('class'),
    processed: link.dataset.ai4a11yProcessed,
  });
}
await m.improveAmbiguousLinks(links);

harness.disable:
if (window.__fixLinksPrev) {
  for (const item of window.__fixLinksPrev) {
    if (item.hadAriaLabel) item.link.setAttribute('aria-label', item.ariaLabel);
    else item.link.removeAttribute('aria-label');
    if (item.hadClass) item.link.setAttribute('class', item.className);
    else item.link.removeAttribute('class');
    if (item.processed !== undefined) item.link.dataset.ai4a11yProcessed = item.processed;
    else delete item.link.dataset.ai4a11yProcessed;
  }
  delete window.__fixLinksPrev;
}

